class ClinicalInteractionEngine:
    """
    High-performance clinical adjudication engine for real-time drug interaction screening.
    Supports complex multi-drug regimen matrix cross-matching and risk stratification.
    """

    @classmethod
    def get_monograph(cls, drug_name: str) -> Optional[DrugMonograph]:
        """Retrieves complete clinical monograph for specified pharmaceutical entity."""
        return CLINICAL_DRUG_MONOGRAPHS.get(drug_name.strip().lower())

    @classmethod
    def check_pair(cls, drug1: str, drug2: str) -> Optional[DrugInteractionRecord]:
        """Evaluates interaction between two drug names regardless of order."""
        d1 = drug1.strip().lower().replace(' ', '_').replace('/', '_')
        d2 = drug2.strip().lower().replace(' ', '_').replace('/', '_')
        k1 = f"{d1}_{d2}"
        k2 = f"{d2}_{d1}"
        return CLINICAL_DRUG_INTERACTIONS.get(k1) or CLINICAL_DRUG_INTERACTIONS.get(k2)

    @classmethod
    def screen_medication_regimen(cls, medication_list: List[str]) -> List[DrugInteractionRecord]:
        """
        Cross-screens an entire patient medication regimen against the clinical interaction matrix.
        Returns a deduplicated list of identified clinical interactions.
        """
        interactions: List[DrugInteractionRecord] = []
        seen_pairs: Set[str] = set()
        clean_list = [m.strip() for m in medication_list if m and m.strip()]
        n = len(clean_list)

        for i in range(n):
            for j in range(i + 1, n):
                match = cls.check_pair(clean_list[i], clean_list[j])
                if match and match.pair_id not in seen_pairs:
                    seen_pairs.add(match.pair_id)
                    interactions.append(match)

        return interactions

    @classmethod
    def get_critical_alerts(cls, medication_list: List[str]) -> List[DrugInteractionRecord]:
        """Returns only CONTRAINDICATED and MAJOR severity interactions."""
        all_interactions = cls.screen_medication_regimen(medication_list)
        return [
            item for item in all_interactions
            if item.severity in [InteractionSeverity.CONTRAINDICATED, InteractionSeverity.MAJOR]
        ]

    @classmethod
    def get_total_monographs_count(cls) -> int:
        return len(CLINICAL_DRUG_MONOGRAPHS)

    @classmethod
    def get_total_interactions_count(cls) -> int:
        return len(CLINICAL_DRUG_INTERACTIONS)
